/**
 * This JS file is included in landing pages, as well as client wrappers and provides an interface to log event
 * to elastic search.
 *
 * How to use:
 *      BytroAnalytics.logElasticEntry('ulttest', {data: data})
 *
 */
var BytroAnalytics = {
    onboardingTrackingIndex: 'ultonboarding',
    loggedEvents: {},
    /**
     * Loads the already logged events from local storage
     */
    initLoggedEvents: function () {
        this.loggedEvents = JSON.parse(localStorage.getItem('sup_analytics_logged_events'));
        if (!this.loggedEvents) {
            this.loggedEvents = {};
        }
    },
    /**
     * Updates the already logged events to local storage
     */
    updateLoggedEvents: function () {
        localStorage.setItem('sup_analytics_logged_events', JSON.stringify(this.loggedEvents));
    },
    /**
     * Convenience methods to track specific events
     */
    logLPBodyStart: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpBodyStart',
            eventType: 'onboardInit'
        })
    },
    logLPBodyEnd: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpInteractivityReached ',
            eventType: 'onboardInit'
        })
    },
    logClientBodyStart: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'gameWrapperBodyStart',
            eventType: 'onboardClientInit'
        })
    },
    logClientBodyEnd: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'gameWrapperInteractivityReached',
            eventType: 'onboardClientInit'
        })
    },
    logLPButtonLogin: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonLogin',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonPlay: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonPlay',
            eventType: 'onboardRegister'
        })
    },
    logLPRegisterTypeName: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpRegisterTypeName',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonFacebook: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonFacebook',
            eventType: 'onboardRegister'
        });
    },
    logLPButtonGoogle: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonGoogle',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonApple: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonApple',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonStillfrontId: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonStillfrontId',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonChangeLanguage: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonChangeLanguage',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonRegisterDataInvalid: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonRegisterDataInvalid',
            eventType: 'onboardRegister'
        })
    },
    logLPButtonRegisterDataValid: function () {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: 'lpButtonRegisterDataValid',
            eventType: 'onboardRegister'
        })
    },
    log: function (eventName, eventType) {
        this.logDistinctElasticEvent(this.onboardingTrackingIndex, {
            eventName: eventName,
            eventType: eventType
        })
    },
    /**
     * End of convenience methods
     */

    /**
     * Logs elastic entry event only if this specific event (indexed by addInfo.eventName) has not be logged
     * already in the current [REDACTED]
     *
     * @param {string} indexName
     * @param {object} addInfo
     */
    logDistinctElasticEvent: function(indexName, addInfo) {
        //Do not log events after [REDACTED]
        if (window.[REDACTED]
            return;
        }
        var eventName = addInfo['eventName'];
        if (!this.loggedEvents[eventName]) {
            this.loggedEvents[eventName] = eventName;
            this.updateLoggedEvents();
            // Do not log when eventName is lpBodyStart and lpInteractivityReached
            if (eventName === 'lpBodyStart' || eventName === 'lpInteractivityReached') {
                return;
            }
            this.logElasticEntry(indexName, addInfo);
        }
    },
    /**
     * Logs event to elastic entry
     * @param indexName
     * @param addInfo
     */
    logElasticEntry: function(indexName, addInfo){
        var data = {
            index: indexName
        };
        if (addInfo) {
            for (var key in addInfo) {
                if (addInfo.hasOwnProperty(key)) {
                    data[key] = addInfo[key];
                }
            }
        }
        this.sendApiRequest('log', {logFormat: 'elasticEntry', json: JSON.stringify(data)});
    },
    /**
     * @param {string} action
     * @param {object} data
     */
    sendApiRequest: function(action, data){
        var e;
        var key = 'open';
        var paramParts = [];
        //build URL query string (userID=123&myVar=1)
        //this used to be done with jQuery's $.param(data), but that one did not handle Functions correctly
        for (e in data) {
            if (data.hasOwnProperty(e)) {
                var str = encodeURIComponent(e) + "=";
                if (data[e] !== undefined) { //otherwise this will resolve to the string "undefined" in the hash base, which is not correct
                    str += encodeURIComponent(data[e]);
                }
                paramParts.push(str);
            }
        }
        var asParam = paramParts.join("&");
        var encoded = btoa(asParam); //base64_encodes the query string
        var postData = 'data='+encoded;
        var rawData;
        rawData = key+action+encodeURIComponent(encoded); //encodeURIComponent == urlencode
        var hash = Crypto.SHA1(rawData);
        var apiUrl = 'index.php?eID=api&key=' + key;
        var url = apiUrl+'&action='+action+'&hash='+hash+'&outputFormat=json' + '&' + postData;
        var request = new XMLHttpRequest();
        request.open( 'POST', url, true);
        request.send();
    }
};

BytroAnalytics.initLoggedEvents();

